-- Phase S step 3: the Price List from klingit-price-list-credits-2026.csv (data/pricing/). Fixed credits per
-- deliverable with a status (fixed / estimate / quote / legacy), the balance it draws on (creative or pm), a monthly
-- flag for fixed-credit services, client visibility, version and valid-from. The old tiered rows are archived, never
-- deleted: old estimate lines keep their link. Credit columns become fractional (0.5 credits): SQLite keeps the
-- stored values, the Prisma schema reads them as Float.
PRAGMA foreign_keys=OFF;
CREATE TABLE "new_PriceListItem" (
    "id" TEXT NOT NULL PRIMARY KEY,
    "deliverableType" TEXT NOT NULL,
    "displayName" TEXT,
    "category" TEXT,
    "squad" TEXT,
    "unit" TEXT,
    "complexityTier" TEXT,
    "creditCost" REAL,
    "balance" TEXT NOT NULL DEFAULT 'creative',
    "status" TEXT NOT NULL DEFAULT 'fixed',
    "monthly" BOOLEAN NOT NULL DEFAULT false,
    "notes" TEXT,
    "leadTimeDays" INTEGER,
    "visibleToClients" BOOLEAN NOT NULL DEFAULT true,
    "version" INTEGER NOT NULL DEFAULT 1,
    "validFrom" DATETIME NOT NULL,
    "sourceKey" TEXT,
    "sortOrder" INTEGER NOT NULL DEFAULT 0,
    "archivedAt" DATETIME,
    "createdAt" DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" DATETIME NOT NULL
);
SELECT "id", "deliverableType", "displayName", "unit", "complexityTier", "creditCost", "notes", "leadTimeDays", "createdAt", 1000, COALESCE("archivedAt", CAST(strftime('%s','now') AS INTEGER) * 1000), "createdAt", "updatedAt" FROM "PriceListItem";
DROP TABLE "PriceListItem";
ALTER TABLE "new_PriceListItem" RENAME TO "PriceListItem";
CREATE UNIQUE INDEX "PriceListItem_sourceKey_key" ON "PriceListItem"("sourceKey");
CREATE INDEX "PriceListItem_deliverableType_idx" ON "PriceListItem"("deliverableType");
PRAGMA foreign_key_check;
PRAGMA foreign_keys=ON;


-- Estimates: each line draws on the PM or the creative balance; estimate and quote lines need the PM's number.
ALTER TABLE "EstimateLineItem" ADD COLUMN "balance" TEXT NOT NULL DEFAULT 'creative';
ALTER TABLE "EstimateLineItem" ADD COLUMN "needsConfirm" BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE "EstimateLineItem" ADD COLUMN "confirmedAt" DATETIME;
ALTER TABLE "EstimateLineItem" ADD COLUMN "confirmedByStaffId" TEXT;
ALTER TABLE "EstimateLineItem" ADD COLUMN "taskType" TEXT;
ALTER TABLE "Estimate" ADD COLUMN "pmCredits" REAL NOT NULL DEFAULT 0;
ALTER TABLE "Estimate" ADD COLUMN "creativeCredits" REAL NOT NULL DEFAULT 0;
UPDATE "Estimate" SET "creativeCredits" = "totalCredits";

-- Plan's per-format lead times can point at a Price List item; the item's lead time then wins.
ALTER TABLE "PlanLeadTime" ADD COLUMN "priceListKey" TEXT;
UPDATE "PlanLeadTime" SET "priceListKey" = 'unique_social_media_design_1_post' WHERE "format" = 'Post';
UPDATE "PlanLeadTime" SET "priceListKey" = 'email_copy_1_marketing_email' WHERE "format" = 'Email';
